//#region src/renderer/src/lib/workspace/worktreeActions.ts
function names(worktree) {
	return {
		branch: worktree.branch ?? "this worktree",
		base: worktree.baseBranch ?? "its base"
	};
}
function plural$8(count, word) {
	return `${count} ${word}${count === 1 ? "" : "s"}`;
}
async function mergeWorktreeFlow(project, worktree, deps) {
	const { branch, base } = names(worktree);
	try {
		const check = await window.agentmat.worktrees.mergePreflight(project.id, worktree.id);
		if (!check.ok) {
			deps.notify.error("Not ready to merge", { description: mergeBlockerMessage(check.blocker, branch, base) });
			return "blocked";
		}
		if (!await deps.confirm({
			title: `Merge ${branch} into ${base}?`,
			description: `The merge happens in the main checkout at ${project.folderPath}. Nothing is pushed.`,
			confirmLabel: "Merge"
		})) return "cancelled";
		const result = await window.agentmat.worktrees.merge(project.id, worktree.id);
		if (result.ok) {
			deps.notify.success(`Merged ${branch} into ${base}`, {
				description: result.message,
				action: {
					label: "Remove worktree",
					onClick: () => deps.openRemove(project.id, worktree.id)
				}
			});
			return "merged";
		}
		deps.notify.warning(`${branch} and ${base} conflict`, {
			description: `${plural$8(result.conflicts.length, "file")} would conflict: ${result.conflicts.join(", ")}. Nothing was changed. Bring ${base} into this worktree and resolve them there.`,
			action: {
				label: `Merge ${base} in here`,
				onClick: () => void mergeBaseInFlow(project, worktree, deps)
			}
		});
		return "conflict";
	} catch (error) {
		deps.notify.error("Merge failed", { description: ipcErrorMessage(error, "Git refused.") });
		return "failed";
	}
}
/** Merges the base into the worktree's branch, leaving any conflict there to resolve. */
async function mergeBaseInFlow(project, worktree, deps) {
	const { branch, base } = names(worktree);
	try {
		const result = await window.agentmat.worktrees.mergeBaseIn(project.id, worktree.id);
		if (result.ok) {
			deps.notify.success(`Merged ${base} into ${branch}`, { description: result.message });
			return "merged";
		}
		deps.openWorkspace(asWorkspaceProject(project, worktree).id);
		deps.revealChanges();
		deps.notify.info(`Resolve ${plural$8(result.conflicts.length, "conflict")} in ${branch}`, { description: "They are listed under Conflicts. Commit once they are resolved, then merge again." });
		return "conflict";
	} catch (error) {
		deps.notify.error("Merge failed", { description: ipcErrorMessage(error, "Git refused.") });
		return "failed";
	}
}
