function runTone(item) {
	if (item.status !== "completed") {
		if (item.status === "queued" || item.status === "waiting" || item.status === "pending") return {
			outcome: "queued",
			label: "Queued",
			variant: "warning"
		};
		return {
			outcome: "running",
			label: "Running",
			variant: "warning"
		};
	}
	if (item.conclusion === "success") return {
		outcome: "passed",
		label: "Passed",
		variant: "success"
	};
	if (item.conclusion === "failure") return {
		outcome: "failed",
		label: "Failed",
		variant: "destructive"
	};
	if (item.conclusion === "timed_out") return {
		outcome: "failed",
		label: "Timed out",
		variant: "destructive"
	};
	if (item.conclusion === "cancelled") return {
		outcome: "cancelled",
		label: "Cancelled",
		variant: "outline"
	};
	if (item.conclusion === "skipped") return {
		outcome: "other",
		label: "Skipped",
		variant: "outline"
	};
	return {
		outcome: "other",
		label: item.conclusion ?? item.status,
		variant: "outline"
	};
}
