function useWorkspaceActivity(scopeId) {
	const ended = useTerminalSessionStore((s) => s.ended);
	const open = useWorkspaceStore(useShallow((s) => Object.values(s.workspaces[scopeId]?.tabs ?? {}).filter((tab) => tab.kind === "terminal").map((tab) => tab.id))).filter((id) => !(id in ended));
	const working = useAgentStatusStore((s) => open.filter((id) => s.statuses[id] === "working").length);
	return {
		terminals: open.length,
		working
	};
}
